def head(title, desc, path='/', article_schema=None):
    canonical='https://getpdfpress.com'+path
    schema = article_schema or {"@context":"https://schema.org","@type":"WebApplication","name":"getPDFpress","url":"https://getpdfpress.com/","applicationCategory":"UtilitiesApplication","operatingSystem":"Any","offers":{"@type":"Offer","price":"0","priceCurrency":"USD"}}
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{desc}"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:url" content="{canonical}"><meta property="og:type" content="website"><link rel="stylesheet" href="/output.css"><script type="application/ld+json">{json.dumps(schema)}</script><!-- TODO AdSense later: add Auto Ads script here only after the tool works, legal pages are final, and content is approved. --></head><body>'''

def tools_grid():
    tools=[('/compress-pdf-500kb','🗜️','Compress to 500KB','For job applications and portal uploads'),('/compress-pdf-200kb','📉','Compress to 200KB','For strict forms and tiny limits'),('/merge-pdf','🧩','Merge PDF','Combine multiple PDFs'),('/split-pdf','✂️','Split PDF','Extract pages into a ZIP'),('/jpg-to-pdf','🖼️','JPG to PDF','Turn images into one PDF'),('/pdf-to-jpg','🌄','PDF to JPG','Export pages as images'),('/pdf-to-word','📝','PDF to Word','Requires ConvertAPI setup'),('/word-to-pdf','📄','Word to PDF','Requires ConvertAPI setup')]
    return '<div class="tool-grid">'+''.join(f'<a class="tool-link" href="{u}"><span style="font-size:28px">{i}</span><b>{t}</b><span class="small">{d}</span></a>' for u,i,t,d in tools)+'</div>'

def tool_box(tool='compress', target='500'):
    labels={'compress':'Compress PDF','merge':'Merge PDFs','split':'Split PDF','jpg-to-pdf':'Create PDF','pdf-to-jpg':'Convert to JPG','pdf-to-word':'Convert to Word','word-to-pdf':'Convert to PDF'}
    accept={'compress':'.pdf','merge':'.pdf','split':'.pdf','jpg-to-pdf':'image/jpeg,image/png,image/webp','pdf-to-jpg':'.pdf','pdf-to-word':'.pdf','word-to-pdf':'.doc,.docx'}[tool]
    multiple=' multiple' if tool in ['merge','jpg-to-pdf'] else ''
    note = 'Files upload to the getPDFpress server for processing, then temporary cleanup runs automatically. Do not upload documents you are not allowed to process.'
    target_note = f'<input type="hidden" value="{target}"><p class="small">Target: {target}KB. Best-effort, not guaranteed.</p>' if tool=='compress' else ''
    return f'''<div class="tool-card pdf-tool" data-tool="{tool}" data-target="{target if tool=='compress' else ''}"><div class="uploader"><div class="upload-icon">📎</div><h3>Choose or drop your file{ 's' if multiple else ''}</h3><p class="small">{note}</p><p class="file-name small">No file selected</p><input class="file-input" type="file" accept="{accept}"{multiple}></div>{target_note}<button class="btn primary run-btn" type="button" disabled>{labels[tool]}</button><div class="status"></div><div class="result"><div class="stats"><div class="stat"><span class="small">Original</span><strong class="original-size">0 KB</strong></div><div class="stat"><span class="small">Result</span><strong class="final-size">0 KB</strong></div><div class="stat"><span class="small">Change</span><strong class="saved-size">0%</strong></div></div><a class="btn primary download-link" href="#" onclick="window.getPDFpressDownloadComplete&&window.getPDFpressDownloadComplete()">Download file</a></div></div>'''

def make_tool_page(filename, title, desc, h1, lead, tool='compress', target='500', tips=None):
    tips=tips or []
    path='/' + filename.replace('.html','') if filename!='index.html' else '/'
    html=head(title,desc,path)+header+f'''<main><section class="hero"><div class="wrap hero-grid"><div><span class="eyebrow">Simple, honest PDF tools</span><h1 class="h1">{h1}</h1><p class="lead">{lead}</p><div class="trust-row"><span class="pill">Best-effort targets</span><span class="pill">No fake user claims</span><span class="pill">Temporary processing</span></div></div>{tool_box(tool,target)}</div></section><section class="section"><div class="wrap"><h2>Popular PDF tools</h2>{tools_grid()}</div></section><section class="section"><div class="wrap grid cards-3">'''
    for t in tips:
        html+=f'<article class="card"><h3>{t[0]}</h3><p>{t[1]}</p></article>'
    html+='''</div></section><section class="section"><div class="wrap"><div class="ad-safe"></div></div></section></main>'''+footer+'<script src="/app.js" defer></script></body></html>'
    (pub/filename).write_text(html)

