def make_article(fname,title,answer,steps):
    path='/learn/'+fname.replace('.html','')
    schema={"@context":"https://schema.org","@type":"Article","headline":title,"description":answer,"mainEntityOfPage":"https://getpdfpress.com"+path,"publisher":{"@type":"Organization","name":"getPDFpress"}}
    html=head(title+' | getPDFpress',answer,path,schema)+header+f'''<main class="article"><div class="wrap article-layout"><aside class="toc"><b>On this page</b><a href="#answer">Fast answer</a><a href="#steps">Steps</a><a href="#tips">Tips</a><a href="#related">Related tools</a></aside><article class="prose"><h1>{title}</h1><div id="answer" class="answer"><b>Fast answer:</b> {answer}</div><h2 id="steps">Steps</h2><ol class="checklist">{''.join('<li>'+s+'</li>' for s in steps)}</ol><h2 id="tips">Practical tips</h2><p>PDF compression is a tradeoff between size and readability. Text-based PDFs usually compress cleanly. Scanned PDFs behave more like photo albums, so they need image reduction, page splitting, or lower scan quality.</p><p>For strict upload limits, do not keep recompressing the same file forever. If the document is still too large, remove unneeded pages or create separate uploads when the portal allows it.</p><h2 id="related">Related tools</h2>{tools_grid()}</article></div></main>'''+footer+'</body></html>'
    (learn/fname).write_text(html)
for fname,data in articles.items(): make_article(fname,*data)

